// generar_300_visitas_veterinarias.js
// CHIQUI Entre Señales — Sección "Visitas veterinarias" en Salud (Etapa 1)
//
// Nueva sección desplegable en la página de Salud para registrar las
// visitas al veterinario, tanto FUTURAS (agendadas) como PASADAS
// (historial), en una línea de tiempo:
//
//   PRÓXIMAS   → ordenadas de la más cercana a la más lejana, con
//                "En X días / Mañana / ¡Es hoy!".
//   HISTORIAL  → las que ya pasaron, de la más reciente hacia atrás.
//
// Cada visita guarda: fecha, hora (opcional), tipo, motivo,
// veterinario/clínica y una nota corta. Tipos disponibles:
//   🩺 Control / rutina · 🔬 Exámenes / chequeo ·
//   🤒 Por enfermedad · 💗 Tratamiento continuo (quimio, crónicos)
//
// Si hay una visita próxima dentro de 7 días, el título de la sección
// muestra un aviso ("En 5 días").
//
// ⚠️ IMPORTANTE — REQUIERE SQL:
//   Antes (o después) de correr este script, ejecuta en Supabase el
//   archivo  sql_visitas_veterinarias.sql  (crea la tabla y sus
//   políticas RLS). Sin esa tabla, la sección se ve pero no guarda.
//   → SQL Editor → New snippet → pegar el .sql → Run.
//
// NOTA: Esta es la Etapa 1 (tabla + sección en Salud). La integración
// con Novedades (aviso ≤7 días) y con "Próximos" del dashboard vendrá
// en un segundo script, una vez que confirmes que esta parte funciona.
//
// Uso:
//   node generar_300_visitas_veterinarias.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'components/VisitasVeterinarias.tsx',
    base64: ""
  },
  {
    ruta: 'app/prevencion/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos.')
  console.log('⚠️  RECUERDA ejecutar sql_visitas_veterinarias.sql en Supabase.')
  console.log('Luego: git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
